	);
);

// Quản lý animation RAF cho từng line để chống giật lag khi xoay liên tục
if (!window._pulseWipeRafs) window._pulseWipeRafs = {};

function wipeLine(lineHotspotName, startW, endW, duration, onComplete) {
	if (window._pulseWipeRafs[lineHotspotName]) {
		cancelAnimationFrame(window._pulseWipeRafs[lineHotspotName]);
		delete window._pulseWipeRafs[lineHotspotName];
	}

	var hs = krpano.get('hotspot[' + lineHotspotName + ']');
	if (!hs) return;

	krpano.set('hotspot[' + lineHotspotName + '].alpha', 1.0);
	var startTime = performance.now();

	function step(now) {
		var elapsed = now - startTime;
		var p = Math.min(elapsed / duration, 1.0);
		// Easing: easeOutCubic khi vẽ ra (nhanh rồi hãm), easeInQuad khi rút về
		var ease = (endW > startW)
			? (1.0 - Math.pow(1.0 - p, 3))
			: Math.pow(p, 2);
		var curW = Math.round(startW + (endW - startW) * ease);
		krpano.set('hotspot[' + lineHotspotName + '].crop', '0|0|' + curW + '|160');

		if (p < 1.0) {
			window._pulseWipeRafs[lineHotspotName] = requestAnimationFrame(step);
		} else {
			delete window._pulseWipeRafs[lineHotspotName];
			if (endW === 0) {
				krpano.set('hotspot[' + lineHotspotName + '].alpha', 0.0);
			}
			if (onComplete) onComplete();
		}
	}
	window._pulseWipeRafs[lineHotspotName] = requestAnimationFrame(step);
}

var h = Number(krpano.get('view.hlookat') || 0);
var v = Number(krpano.get('view.vlookat') || 0);
h = ((h % 360) + 540) % 360 - 180;

var count = krpano.get('hotspot.count');
for (var i = 0; i < count; i++) {
	var hsName = krpano.get('hotspot[' + i + '].name');
	var hsStyle = krpano.get('hotspot[' + i + '].style');
	var isPulse = krpano.get('hotspot[' + i + '].is_pulse_dot');

	if (hsStyle === 'pulse_dot' || isPulse === 'true' || isPulse === true) {
		var hsAth = Number(krpano.get('hotspot[' + i + '].ath') || 0);
		var hsAtv = Number(krpano.get('hotspot[' + i + '].atv') || 0);
		hsAth = ((hsAth % 360) + 540) % 360 - 180;

		var dh = h - hsAth;
		if (dh > 180) dh -= 360;
		if (dh < -180) dh += 360;
		var dv = v - hsAtv;
		var dist = Math.sqrt(dh * dh + dv * dv);

		var isFacing = (dist < 20);

		var hsLabel = krpano.get('hotspot[' + hsName + '_label]');
		var hsLine = krpano.get('hotspot[' + hsName + '_line]');

		if (hsLabel) {
			var wasFacing = hsLabel._is_facing;

			if (isFacing && wasFacing !== true) {
				// ═══ WIPE IN (Xuất hiện như video mẫu) ═══
				hsLabel._is_facing = true;

				// 1. Line Wipe: Vẽ từ tâm chấm ra ngoài (crop width: 0 -> 240)
				wipeLine(hsName + '_line', 0, 240, 500);

				// 2. Badge Wipe In: Khi line gần chạm badge (sau 0.18s), badge bung mở từ mút line sang phải
				krpano.set('hotspot[' + hsName + '_label].scale', 0.0);
				krpano.set('hotspot[' + hsName + '_label].alpha', 0.0);
				krpano.call('delayedcall(0.25, tween(hotspot[' + hsName + '_label].scale|hotspot[' + hsName + '_label].alpha, 1.0|1.0, 0.5, easeOutBack); );');

			} else if (!isFacing && wasFacing !== false) {
				// ═══ WIPE OUT (Biến mất ngược lại) ═══
				hsLabel._is_facing = false;

				// 1. Hộp chữ thu nhỏ biến mất về mút line trước
				krpano.call('tween(hotspot[' + hsName + '_label].scale|hotspot[' + hsName + '_label].alpha, 0.0|0.0, 0.2, easeInQuad);');

				// 2. Line Wipe: Rút từ ngoài về lại tâm chấm (crop width: 240 -> 0)
				wipeLine(hsName + '_line', 240, 0, 240);
			}
		}
	}
}

if(caller.linkedscene,
	copy(hs_linkedscene, caller.linkedscene);
	if(caller.linkedscene_lookat, txtsplit(caller.linkedscene_lookat, ',', hs_lookat_h, hs_lookat_v, hs_lookat_fov); );
